function minimizedStringLength(s) {
  // Simulate the moves: keep deleting the nearest earlier copy of some character until no move is possible.
  const chars = s.split('');
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i < chars.length && !changed; i++) {
      for (let j = i - 1; j >= 0; j--) {
        if (chars[j] === chars[i]) {
          chars.splice(j, 1);
          changed = true;
          break;
        }
      }
    }
  }
  return chars.length;
}

