function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'small' ? pick(1, 12) : pick(90, 100);
  const mode = Math.floor(rand() * 4);
  const alphabet = mode === 0 ? 1 : mode === 1 ? pick(2, 4) : mode === 2 ? pick(5, 15) : 26;
  const offset = pick(0, 26 - alphabet);
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + offset + pick(0, alphabet - 1));
  return [s];
}
